    {
      "@id": "activity:translation-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-2026-06-23T08:30:47.117205+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-06-23T08:30:47.117205+00:00",
      "actor": {
        "@id": "agent:OLLAMA-hf.co/s3nh/Unbabel-TowerInstruct-7B-v0.1-GGUF_Q4_K_M_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa",
      "@type": "prov:Entity",
      "prov:value": "That's where Peri comes in. Peri is Peripateticware's AI guide — named, like the software, after the Aristotelian method. Peri doesn't answer questions. It asks them. It follows the five-phase inquiry sequence — Engage, Observe, Analyse, Explain, Apply — that Aristotle used in the Lyceum and that cognitive science has since validated as a path to genuine understanding, not just retention. Peri takes a student's observation and asks the next right question. When the student gets it right, Peri tests the implication. When the student is vague, Peri asks for evidence."
    },
    {
      "@id": "entity:target-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-v1",
      "@type": "prov:Entity",
      "prov:value": "That's where Peri comes in. Peri is Peripateticware's AI guide — named, like the software, after the Aristotelian method. Peri doesn't answer questions. It asks them. It follows the five-phase inquiry sequence — Engage, Observe, Analyse, Explain, Apply — that Aristotle used in the Lyceum and that cognitive science has since validated as a path to genuine understanding, not just retention. Peri takes a student's observation and asks the next right question. When the student gets it right, Peri tests the implication. When the student is vague, Peri asks for evidence.",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-2026-06-23T08:30:47.117205+00:00"
